  const dp = new Array(W + 1).fill(0);
  for (let i = 0; i < weights.length; i++) {
    const wt = weights[i], val = values[i];
    for (let w = wt; w <= W; w++) {   // BUG: ascending reuses item i
      dp[w] = Math.max(dp[w], dp[w - wt] + val);
